# -*- coding: utf-8 -*-
"""Vietnamese teaching explanations for original N2-MOCK-11 items."""
from __future__ import annotations


EXPLANATIONS_VI = {
    # Vocabulary: kanji readings, orthography, context, paraphrase and usage.
    "N2_11_M1_01": "均等（きんとう）nghĩa là chia đều, không để gánh nặng giữa các bộ phận chênh lệch. Chữ 均 đọc きん và 等 đọc とう trong từ này.",
    "N2_11_M1_02": "照合（しょうごう）là đem hai nguồn thông tin ra so sánh để kiểm tra sự trùng khớp. Cách đọc đúng là しょうごう, không phải しょうこう.",
    "N2_11_M1_03": "優先（ゆうせん）nghĩa là xếp một việc lên trước việc khác. Câu nói đặt an toàn lên trên cắt giảm chi phí; từ được đọc là ゆうせん.",
    "N2_11_M1_04": "改める（あらためる）nghĩa là sửa đổi hoặc làm mới nội dung. ためらう lại có nghĩa là do dự, nên không hợp với việc sửa điều kiện hợp đồng.",
    "N2_11_M1_05": "踏まえる（ふまえる）là cân nhắc một kinh nghiệm hay căn cứ trước khi hành động. Dạng nối với て là 踏まえて（ふまえて）.",
    "N2_11_M2_01": "交渉（こうしょう）là thương lượng để thống nhất điều kiện như thời hạn giao hàng. 高尚 chỉ điều cao đẹp, 公称 là tên gọi/chỉ số được công bố, còn 口承 là sự truyền miệng.",
    "N2_11_M2_02": "干渉（かんしょう）là can thiệp quá mức vào công việc của người khác. 鑑賞 là thưởng thức tác phẩm, 感傷 là cảm xúc đa sầu, còn 緩衝 là làm dịu va chạm hoặc tác động.",
    "N2_11_M2_03": "校正（こうせい）là rà bản thảo để sửa lỗi chữ và lỗi in trước khi công bố. 構成 là bố cục, 公正 là công bằng, còn 更生 là làm lại cuộc đời hoặc phục hồi.",
    "N2_11_M2_04": "検討（けんとう）là xem xét và so sánh nhiều phương án trước khi quyết định. 見当 là ước lượng, 健闘 là nỗ lực thi đấu tốt, còn 拳闘 là môn quyền Anh.",
    "N2_11_M2_05": "保証（ほしょう）là cam kết về chất lượng hoặc tình trạng của sản phẩm. 補償 là bồi thường thiệt hại, 保障 là bảo vệ quyền/lợi ích, còn 歩哨 là người lính gác.",
    "N2_11_M3_01": "Khi trả lời thư hay liên lạc của đối tác, dùng 返信する. 返済 là trả nợ, 返還 là hoàn trả vật hoặc quyền, còn 返却 là trả lại đồ đã mượn.",
    "N2_11_M3_02": "人 数に応じて nghĩa là điều chỉnh số lượng theo số người tham dự. 沿って chỉ làm theo một đường lối, còn 対して và 伴って không diễn tả quan hệ số lượng cần thiết ở đây.",
    "N2_11_M3_03": "採用するかどうか検討している nghĩa là đang cân nhắc có áp dụng đề xuất hay không. 観察 là quan sát, 反省 là tự nhìn lại, 想像 là tưởng tượng.",
    "N2_11_M3_04": "Thời gian họp thay đổi nên cần 連絡する, tức báo ngay cho những người có liên quan. 接続 là kết nối, 交際 là giao tiếp/quan hệ, còn 応対 là tiếp khách hoặc xử lý yêu cầu.",
    "N2_11_M3_05": "保留 nghĩa là tạm để việc xử lý chờ thông tin bổ sung. Khoản thanh toán đang lệch hợp đồng nên cần dừng thủ tục tới khi xác minh; 継続, 完了 và 撤回 lần lượt là tiếp tục, hoàn tất và rút lại.",
    "N2_11_M4_01": "急な依頼に合わせて予定を調整する nghĩa là sắp xếp lại lịch để đáp ứng yêu cầu đột xuất. 調節 thường điều chỉnh mức độ hoặc thiết bị; 整理 là sắp xếp, còn 整列 là xếp thành hàng.",
    "N2_11_M4_02": "反対意見も考慮する là đưa cả ý kiến phản đối vào làm căn cứ trước khi quyết định. 考察 là phân tích, 考案 là nghĩ ra phương án, còn 予想 là dự đoán.",
    "N2_11_M4_03": "小さく試行する là thử nghiệm quy mô nhỏ để xem quy trình có hiệu quả không. 試着 dùng cho thử quần áo, 試食 cho nếm món ăn; 試験 thiên về kiểm tra hoặc kỳ thi.",
    "N2_11_M4_04": "Khi người phụ trách nghỉ, đồng nghiệp trong cùng bộ phận làm 代理を務める, tức thay mặt người đó đảm nhận nhiệm vụ. 代表 là đại diện một tập thể; 代用 là dùng vật khác thay thế.",
    "N2_11_M4_05": "運用を改善する nghĩa là cải tiến cách vận hành dựa trên ý kiến người dùng. 改定 là sửa đổi quy định/phiên bản, 改造 là cải tạo cấu trúc, còn 改訳 là dịch lại.",
    "N2_11_M4_06": "ICレコーダー dùng để thu và lưu âm thanh, nên động từ đúng là 録音する. 記載 là ghi chữ vào tài liệu; 記憶 là ghi nhớ trong đầu, còn 記念 mang nghĩa kỷ niệm.",
    "N2_11_M4_07": "Muốn kịp hạn, người phụ trách đã xem xét và điều chỉnh lại thứ tự công việc; dạng quá khứ là 見直した. 見逃した là bỏ sót, 見送った là không tiến hành, còn 見込んだ là dự tính.",
    "N2_11_M5_01": "踏まえて diễn tả việc lấy một thông tin làm căn cứ khi hành động. Vì vậy, phát biểu trong cuộc họp được dùng làm cơ sở để sửa kế hoạch, không bị bỏ qua hay hủy bỏ.",
    "N2_11_M5_02": "状況に即している nghĩa là phù hợp với tình hình thực tế tại nơi làm việc. Nó không có nghĩa là né tránh, che giấu hay chủ động thay đổi tình hình.",
    "N2_11_M5_03": "補う là thêm phần còn thiếu. Người phụ trách gửi kèm tài liệu sau đó để bù cho phần giải thích chưa đủ, không phải để rút ngắn nội dung.",
    "N2_11_M5_04": "連携する là phối hợp và làm việc cùng nhau hướng tới mục tiêu chung. Câu không nói hai bộ phận cạnh tranh, tách rời hay thay phiên nhau.",
    "N2_11_M5_05": "前倒しする là chuyển công việc lên thời điểm sớm hơn dự kiến. Câu cho biết người phụ trách làm sớm để kịp thời hạn, không phải dời lịch muộn hơn.",
    "N2_11_M6_01": "見送る ở đây là quyết định chưa thực hiện một kế hoạch sau khi cân nhắc, vì vậy việc hoãn đưa hệ thống mới vào dùng do chưa rõ hiệu quả là tự nhiên. 見送る ở câu về nhà ga lại có nghĩa tiễn ai đó, còn các câu khác ghép động từ với tân ngữ không phù hợp.",
    "N2_11_M6_02": "差し支える nghĩa là gây trở ngại hoặc bất tiện. Một khung giờ không phù hợp cho cuộc họp có thể diễn đạt là 打ち合わせに差し支える; từ này không tả tính cách hay hành động cầm tài liệu.",
    "N2_11_M6_03": "取りまとめる là tập hợp và sắp xếp nhiều ý kiến/thông tin thành một bản tổng hợp. Ý kiến của các phòng ban được gom lại thành báo cáo; không dùng từ này để sửa bàn, ăn trưa hay đeo thẻ.",
    "N2_11_M6_04": "見込む trong câu này là dự đoán lượng yêu cầu sẽ tăng trong tương lai, nên công ty tăng nhân sự trước. Các câu về nhìn khuôn mặt, cảnh vật hay mép giấy không dùng nghĩa dự báo.",
    "N2_11_M6_05": "行き違い là sự lệch nhau trong thông tin/liên lạc khiến hai bên hiểu khác hoặc hành động khác nhau. Vì liên lạc không khớp nên hai người đi tới hai địa điểm khác nhau.",

    # Grammar: form selection, ★ composition and text grammar.
    "N2_11_M7_01": "確認したほうがいい dùng để khuyên nên kiểm tra. Vì câu nhắc việc cần làm trước khi gửi tài liệu, mẫu khuyến nghị này phù hợp hơn nghĩa một chiều, vừa mới làm hay không cần làm.",
    "N2_11_M7_02": "説明したうえで適用する diễn tả làm xong bước giải thích rồi mới áp dụng quy định. Cấu trúc うえで nối hai bước theo trình tự.",
    "N2_11_M7_03": "ないことには diễn tả điều kiện bắt buộc: nếu không thay đổi cài đặt thì không thể giải quyết lỗi. Câu có phủ định trước chỗ trống nên cần mẫu này.",
    "N2_11_M7_04": "ものの nối hai ý tương phản: dù đã giải thích việc đổi lịch, người nói vẫn chưa xác nhận mọi người đều nhận được thông tin. ために và だけに nêu nguyên nhân, còn うえで biểu thị thứ tự hoặc điều kiện sau khi làm xong.",
    "N2_11_M7_05": "記入したうえで提出する nghĩa là điền đủ thông tin rồi mới nộp đơn. うえで biểu thị bước trước đã hoàn tất trước khi làm bước sau.",
    "N2_11_M7_06": "からといって…わけではない có nghĩa không thể kết luận rằng chỉ vì một lý do thì điều kia được phép. Ngân sách hạn chế không đồng nghĩa với việc được hạ chất lượng.",
    "N2_11_M7_07": "経験が浅いながらも diễn tả sự tương phản: dù kinh nghiệm còn ít, người phụ trách vẫn làm việc cẩn thận. ながらも nối hai ý trái kỳ vọng.",
    "N2_11_M7_08": "共有するにあたって nghĩa là khi chuẩn bị/thực hiện việc chia sẻ thì cần kiểm tra quyền xem. Đây là lưu ý đi kèm một hành động sắp làm.",
    "N2_11_M7_09": "質問が増えているせいか thể hiện phỏng đoán nguyên nhân, không khẳng định chắc chắn rằng câu hỏi tăng là do lời giải thích khó hiểu.",
    "N2_11_M7_10": "期限に遅れないように確認する diễn tả mục đích/phòng ngừa: kiểm tra tiến độ để tránh trễ hạn. ように phù hợp với hành động hướng tới kết quả này.",
    "N2_11_M7_11": "状況に応じて見直す là xem xét lại tùy theo tình hình thay đổi. 応じて diễn tả sự điều chỉnh theo điều kiện thực tế.",
    "N2_11_M7_12": "数字の正確さを確かめるとともに出典も明記する liệt kê hai việc cần làm song song. とともに nối các yêu cầu cùng được thực hiện.",
    "N2_11_M8_01": "Thứ tự là まず請求書の金額を → 注文記録と照合し → その結果、差があった場合は取引先に確認してから → 修正案を作る. Cụm đứng thứ ba là その結果…; từ này cần kết quả đối chiếu ở cụm trước.",
    "N2_11_M8_02": "結論を急ぐより根拠を確かめることのほうが大切だ tạo cấu trúc so sánh: kiểm tra căn cứ quan trọng hơn vội kết luận. Cụm ことのほうが đứng thứ ba.",
    "N2_11_M8_03": "Thứ tự đúng là まず請求書の金額を → 注文記録と照合し → 差があれば取引先に確認してから → 支払いの手続きを進める. Cụm thứ ba nêu điều kiện xử lý sau khi phát hiện chênh lệch.",
    "N2_11_M8_04": "Thứ tự là 申請書に記された数字と → 原本の数字を → 項目ごとに照合し → その結果、違いがある項目は申請者に確認する必要がある. Cụm thứ ba hoàn tất động từ 照合する trước khi nêu kết quả.",
    "N2_11_M8_05": "Thứ tự là 相手の立場を → 理解しようとする → 姿勢を保つ → ことは必要だ. Cụm 姿勢を保つ hoàn thành ý “giữ thái độ cố gắng hiểu lập trường của đối phương” và đứng ở vị trí thứ ba.",
    "N2_11_M9_01": "というわけではない phủ định việc kết luận tuyệt đối rằng thông tin càng nhiều thì liên lạc càng tốt. Đoạn văn chuyển sang yêu cầu chọn thông tin người đọc thật sự cần.",
    "N2_11_M9_02": "とともに ở đây nối hai nội dung song song trong biên bản: ghi lại lý do của từng ý kiến và lưu cả mối lo cụ thể được nêu ra. ものの diễn tả nhượng bộ, còn に先立って nói về thứ tự trước sau; chúng không diễn đạt quan hệ bổ sung giữa hai mục cần lưu.",
    "N2_11_M9_03": "調べないことには解決の手掛かりが得られない nghĩa là nếu không kiểm tra và tìm điều kiện tái hiện thì chưa thể có đầu mối giải quyết.",
    "N2_11_M9_04": "に先立って cho biết nhân viên thử màn hình trước khi đưa vào vận hành chính thức. を通じて chỉ khoảng thời gian diễn ra trong lúc vận hành, trái với yêu cầu kiểm tra trước khi công bố ở câu trước.",
    "N2_11_M9_05": "条件が異なる以上、単純比較すべきでない nêu kết luận dựa trên tiền đề các điều kiện khảo sát khác nhau. 以上 biểu thị “đã là/vì… thì”.",

    # Reading comprehension: decisive details and inference.
    "N2_11_M10_01": "Ngày tạo và số phiên bản giúp nhân viên nhận ra tệp nào mới hơn khi tên tệp chưa đủ rõ. Mục đích được nêu là phân biệt độ mới của tệp, không phải giảm dung lượng.",
    "N2_11_M10_02": "Người phụ trách không tự đoán khoản tiền chưa rõ mà đánh dấu chỗ cần hỏi đối tác. Chi tiết này cho thấy họ muốn tránh nhập một con số không có căn cứ.",
    "N2_11_M10_03": "Giảng viên yêu cầu xóa cảnh có tên người tham gia trước khi chia sẻ video. Đây là bước bảo vệ thông tin cá nhân trước khi công bố.",
    "N2_11_M10_04": "Thông báo cũ còn ghi địa điểm cũ sau khi phòng họp đổi. Gửi bản sửa giúp người tham gia không đi nhầm tới địa điểm trước đó.",
    "N2_11_M10_05": "Thời gian xử lý việc phát sinh sẽ được dùng vào tháng sau để ước lượng khối lượng công việc. Mục tiêu là cải thiện dự báo, không phải tính lương hay đánh giá cá nhân.",
    "N2_11_M11_01": "Bảng bàn giao gồm việc chưa xong, ngày cần kiểm tra tiếp theo và thông tin liên hệ. Bài đọc liệt kê đúng ba trường này.",
    "N2_11_M11_02": "Nếu không cập nhật trạng thái, bảng nhanh chóng trở thành thông tin cũ. Vì vậy người xử lý cần sửa bảng trong ngày và người nhận kiểm tra vào sáng hôm sau.",
    "N2_11_M11_03": "Bài đọc nói các trường hợp cần quyết định ngoại lệ không thể chỉ dựa vào bảng; nhóm vẫn bố trí thời gian bàn giao trực tiếp.",
    "N2_11_M11_04": "Người tham dự chưa đọc tài liệu nên cuộc họp phải dành thời gian thống nhất lại các tiền đề, khiến chưa thể vào phần cần quyết định.",
    "N2_11_M11_05": "Nhóm gửi tài liệu trước một ngày và yêu cầu mỗi người ghi sẵn một câu hỏi. Mục tiêu là bắt đầu cuộc họp bằng câu hỏi và so sánh lựa chọn.",
    "N2_11_M11_06": "Một số người mất quá nhiều thời gian chuẩn bị, nên nhóm giới hạn tài liệu chính trong hai trang và chuyển chi tiết sang phụ lục dành cho người cần xem.",
    "N2_11_M11_07": "Khi nhân viên cảm thấy sẽ bị trách nếu báo cáo, họ có xu hướng giấu lỗi nhỏ. Tác giả nêu cảm nhận bị đổ lỗi là nguyên nhân trực tiếp.",
    "N2_11_M11_08": "Sau khi nhận báo cáo, quản lý trước tiên kiểm tra sự việc thực tế và phạm vi ảnh hưởng, rồi mới bàn về phòng ngừa tái diễn.",
    "N2_11_M11_09": "Cơ chế không xóa bỏ trách nhiệm; nó phân biệt vi phạm cố ý với lỗi do thiếu quy trình/thông tin để tìm phần có thể cải thiện ở cấp tổ chức.",
    "N2_11_M12_01": "Kimura là nhân viên mới và muốn học trực tuyến vào giờ nghỉ trưa. Chỉ khóa B dành cho mọi nhân viên, học trực tuyến vào thứ Năm buổi trưa.",
    "N2_11_M12_02": "Sato là quản lý nhưng bận họp vào giờ trưa thứ Năm. Trong các khóa dành cho quản lý, chỉ khóa C vào thứ Sáu có thể phù hợp; vẫn cần đáp ứng hạn đăng ký.",
    "N2_11_M13_01": "Thời gian xử lý không phản ánh các ngoại lệ hay việc giải thích cho người dùng. Tự động hóa chỉ dựa vào số phút có thể bỏ sót những phần việc quan trọng này.",
    "N2_11_M13_02": "Người trả lời và người không trả lời khảo sát có thể khác nhau về mức quan tâm hoặc kinh nghiệm sử dụng. Vì vậy số lượng phản hồi lớn chưa chắc đại diện cho toàn bộ người dùng.",
    "N2_11_M13_03": "Đổi mọi thuật ngữ thành từ đơn giản có thể làm mất những phân biệt quan trọng. Tác giả đề xuất giữ thuật ngữ cần thiết và giải thích bằng ví dụ gần đó.",
    "N2_11_M14_01": "Hạn gửi email đăng ký là 17 giờ thứ Sáu, ngày 12 tháng 6. Ngày 15 tháng 6 là hạn báo kết quả tham dự, không phải hạn đăng ký.",
    "N2_11_M14_02": "Hướng dẫn ghi rõ người đi từ tòa Tây sang tòa Đông cần dùng hành lang nối. Hội trường ở tầng bốn tòa Đông, còn quầy tiếp nhận ở tầng một.",

    # Listening: identify the requested action, condition, discourse point or response.
    "N2_11_M1_L01": "Trưởng nhóm yêu cầu kiểm tra tồn kho và phần in còn lại trước khi trả lời đối tác. Chưa được gửi toàn bộ ngay; nếu thiếu thì phải hỏi xem có thể gửi thành nhiều đợt không.",
    "N2_11_M1_L02": "Đối tác chưa biết thông số sản phẩm nên người phụ trách chuẩn bị tài liệu hướng dẫn cách sử dụng trước. Giá và lịch thăm không phải bước được yêu cầu.",
    "N2_11_M1_L03": "Nhân viên không cần hủy đơn đã nộp. Họ cần gửi email bản đã sửa, đánh dấu rõ mục thay đổi để nhân sự nhận biết.",
    "N2_11_M1_L04": "Cấp trên nói phải đối chiếu danh sách người tham dự với địa chỉ email trước khi sửa tài liệu. Đây là thao tác đầu tiên để tránh bỏ sót thư mời.",
    "N2_11_M1_L05": "Vì thiếu biên lai, nhân viên phải xem hồ sơ chuyến đi để kiểm tra tuyến đường và số tiền. Họ được dặn không khai một khoản ước lượng từ trí nhớ.",
    "N2_11_M2_L01": "Nếu số người đăng ký vượt quá 20 chỗ, ban tổ chức sẽ chọn người tham dự bằng hình thức bốc thăm, không nhận theo thứ tự gửi đơn.",
    "N2_11_M2_L02": "Nhân viên được dặn nhập báo cáo trên điện thoại vào lúc kết thúc ngày phải đi thẳng về nhà, không phải trước khi rời công ty.",
    "N2_11_M2_L03": "Khi chưa xác minh xong, hãy ghi trạng thái “đang kiểm tra” và người phụ trách. Không để trống hoặc tự điền giá trị phỏng đoán.",
    "N2_11_M2_L04": "Tài liệu chưa rõ nơi lưu phải được ghi vào danh sách và giữ lại trong khi chờ bộ phận liên quan xác nhận, không tự xóa.",
    "N2_11_M2_L05": "Theo quy tắc chung, phải xin cấp trên phê duyệt trước khi đặt khách sạn; chỉ trường hợp thay đổi đột xuất mới là ngoại lệ.",
    "N2_11_M2_L06": "Thiết bị phải được mang đến trong trạng thái sử dụng bình thường, không khôi phục cài đặt gốc. Không cần chuyển dữ liệu cá nhân lên nơi chia sẻ của công ty.",
    "N2_11_M3_L01": "Người nói cho rằng đánh giá khóa học chỉ qua mức hài lòng là chưa đủ; cần xem học viên đã áp dụng điều gì trong công việc sau khóa học.",
    "N2_11_M3_L02": "Nên ghi lại nội dung yêu cầu của khách hàng và trạng thái xử lý để cả bộ phận dùng được, đồng thời chỉ chia sẻ dữ liệu cá nhân ở mức cần thiết.",
    "N2_11_M3_L03": "Bàn giao cần nêu cả trường hợp ngoại lệ và nội dung chưa chốt, vì sổ tay thường chỉ mô tả luồng làm việc thông thường.",
    "N2_11_M3_L04": "Người nói khuyên giữ thuật ngữ cần thiết nhưng thêm lời giải thích ngắn, tiêu đề và ví dụ để người đọc hiểu đúng điều kiện.",
    "N2_11_M3_L05": "Chia sẻ câu hỏi trước cuộc họp và cho người tham dự thời gian suy nghĩ sẽ giúp ý kiến có nội dung sâu hơn, thay vì yêu cầu trả lời ngay.",
    "N2_11_M4_L01": "Đồng nghiệp báo rằng tài liệu đã được đưa vào thư mục chia sẻ. Cảm ơn và nói sẽ kiểm tra là phản hồi phù hợp với thông tin này.",
    "N2_11_M4_L02": "Người nghe được nhờ gửi lại bản báo giá, nên xác nhận sẽ gửi ngay là phản hồi trực tiếp và lịch sự.",
    "N2_11_M4_L03": "Người đối diện đề nghị tự giải thích với đối tác. Nhận lời và cảm ơn sự hỗ trợ khớp với lời đề nghị.",
    "N2_11_M4_L04": "Người nói xin lỗi vì không thể dự buổi trao đổi hôm nay. Xác nhận đã hiểu và đề nghị tìm ngày khác là cách xử lý phù hợp.",
    "N2_11_M4_L05": "Người đối diện chỉ ra con số khác báo cáo cũ; đáp lại rằng sẽ kiểm tra và sửa nếu cần trực tiếp giải quyết vấn đề được nêu.",
    "N2_11_M4_L06": "Người hỏi muốn xác nhận hạn nộp vào thứ Sáu. Trả lời cụ thể đến 17 giờ làm rõ chính xác thời điểm kết thúc.",
    "N2_11_M4_L07": "Câu hỏi hỏi việc bàn giao đã hoàn tất chưa. Xác nhận đã xong và đã giao cả tài liệu trả lời đúng cả tiến độ lẫn vật cần chuyển.",
    "N2_11_M4_L08": "Đây là lời nhờ kiểm tra email kèm lời xin lỗi vì làm phiền. Nhận lời và hẹn xem trong ngày là phản hồi tự nhiên.",
    "N2_11_M4_L09": "Nếu không đặt được địa điểm, cần tìm ngày ứng viên khác. Phản hồi đề xuất kiểm tra thêm ngày phù hợp với câu hỏi về phương án tiếp theo.",
    "N2_11_M4_L10": "Số người dự kiến tăng, nên nhóm đề xuất xem có thể đổi sang hội trường rộng hơn hay không. Câu trả lời này xử lý trực tiếp nguy cơ thiếu chỗ.",
    "N2_11_M4_L11": "Người hỏi chưa biết nộp giấy ở đâu. Chỉ dẫn đến quầy tiếp nhận của phòng Tổng vụ cung cấp đúng địa điểm cần tìm.",
    "N2_11_M5_L01": "Lịch ban đầu là thứ Ba nhưng giảng viên bận; phòng nhỏ vẫn đủ chỗ cho 12 người. Vì vậy hai người thống nhất chuyển buổi học sang sáng thứ Năm.",
    "N2_11_M5_L02": "Hai người giữ khóa đào tạo nhưng rút ngắn thời lượng chung; các bộ phận khó thao tác sẽ được giải thích bổ sung. Cách này cân bằng chi phí và nhu cầu hỗ trợ.",
    "N2_11_M5_L03": "Họ chọn trình bày các chức năng cần thiết, chuyển thông tin chi tiết sang tài liệu riêng và dành 15 phút cuối cho câu hỏi.",
}


def _option_clause(option_text: str, explanation: str) -> str:
    """Extract an authored contrast when the explanation names this distractor."""
    start = explanation.find(option_text)
    if start < 0:
        return ""
    left_candidates = [explanation.rfind(mark, 0, start) for mark in ".。;；,，"]
    left = max(left_candidates) + 1
    right_candidates = [position for mark in ".。;；,，" if (position := explanation.find(mark, start)) >= 0]
    right = min(right_candidates) if right_candidates else len(explanation)
    clause = explanation[left:right].strip(" ：:、，")
    return clause if len(clause) >= 8 else ""


def _distractor_reason(item: dict, option: dict, correct_text: str, explanation: str) -> str:
    option_text = option["text"]
    qid = item["id"]
    if item.get("typeId") == "N2-GR-STAR":
        order = item.get("fragmentOrder", "").replace("→", " → ")
        return (f"«{option_text}» không nằm ở vị trí ★ trong chuỗi tạo câu tự nhiên. "
                f"Trật tự đúng là {order}; cụm thứ ba là «{correct_text}». "
                f"Câu hoàn chỉnh: {item.get('assembledSentence', '')}。")

    authored_contrast = _option_clause(option_text, explanation)
    if authored_contrast:
        return f"«{option_text}»: {authored_contrast}. Phần giải thích dưới đây đặt từ/cấu trúc này cạnh nghĩa cần dùng trong câu."

    if str(item.get("typeId", "")).startswith("N2-LIS-"):
        label = "Lời thoại" if item.get("script") else "Nội dung nghe"
        return (f"«{option_text}» không khớp với dữ kiện trong audio. {label} cho biết: "
                f"{explanation} Vì vậy, lựa chọn này đổi hành động, thời điểm hoặc điều kiện được nói đến.")

    if str(item.get("typeId", "")).startswith("N2-RD-"):
        return (f"«{option_text}» không được đoạn văn hỗ trợ. Căn cứ cần đối chiếu là: "
                f"{explanation} Phương án này thêm hoặc đổi chi tiết so với thông tin đó.")

    if str(item.get("typeId", "")).startswith("N2-GR-"):
        return (f"«{option_text}» biểu thị quan hệ ngữ pháp khác với câu này. "
                f"Ngữ cảnh cần: {explanation}")

    if str(item.get("typeId", "")).startswith("N2-MO-"):
        return (f"«{option_text}» không diễn tả đúng nghĩa/cách dùng được hỏi. "
                f"Đối chiếu nghĩa trong câu: {explanation}")

    return f"«{option_text}» không khớp với căn cứ được nêu: {explanation}"


def apply_vietnamese_explanations(items: list[dict]) -> None:
    ids = {item["id"] for item in items}
    missing = ids - EXPLANATIONS_VI.keys()
    if missing:
        raise ValueError(f"M11 explanation coverage missing for {sorted(missing)}")
    for item in items:
        explanation = EXPLANATIONS_VI[item["id"]]
        item["explanationVi"] = explanation
        correct_text = next(option["text"] for option in item["options"] if option["id"] == item["correctAnswer"])
        item["distractorExplanations"] = {
            option["id"]: _distractor_reason(item, option, correct_text, explanation)
            for option in item["options"] if option["id"] != item["correctAnswer"]
        }
